# -*- coding: utf-8 -*-# p4_evolution.py - Evolution Temporelle 2016-2020import streamlit as stimport plotly.graph_objects as gofrom plotly.subplots import make_subplotsfrom config import C, apply_theme, AXIS_STYLE, SAT_GLOBALfrom components.kpi_cards import kpi_row, section_title, page_headerfrom data.loader import load_evolutiondef render():    page_header(        "Evolution Temporelle",        "Croissance du marche - satisfaction - taux d'internationalisation",        "📅"    )    df = load_evolution()    vol_2019 = int(df[df["Ann\u00e9e"] == 2019]["Nb transactions"].values[0])    vol_2020 = int(df[df["Ann\u00e9e"] == 2020]["Nb transactions"].values[0])    sat_2016 = df[df["Ann\u00e9e"] == 2016]["Note globale"].values[0]    sat_2020 = df[df["Ann\u00e9e"] == 2020]["Note globale"].values[0]    kpi_row([        {"title": "Pic de volume", "value": "{:,}".format(vol_2019),         "subtitle": "2019 (meilleure annee)", "color": "blue", "icon": "📈"},        {"title": "Impact Covid-19", "value": "-{:,}".format(vol_2019 - vol_2020),         "subtitle": "Transactions perdues 2020", "color": "red", "icon": "⚠️"},        {"title": "Progression satisfaction",         "value": "+{:.3f}".format(sat_2020 - sat_2016),         "subtitle": "4.809 a 4.830 sur 5 ans", "color": "green", "icon": "⭐"},        {"title": "Taux intl. 2017", "value": "79.1%",         "subtitle": "Pic d'internationalisation", "color": "teal", "icon": "✈️"},    ])    # ── Dual axis volume + satisfaction ──────────────────────    section_title("Volume et Satisfaction - evolution synchrone", "📊")    fig = make_subplots(specs=[[{"secondary_y": True}]])    fig.add_trace(go.Bar(        x=df["Ann\u00e9e"],        y=df["Nb transactions"],        name="Volume transactions",        marker=dict(            color=[C["blue"] if y < 2020 else C["red"] for y in df["Ann\u00e9e"]],            opacity=0.7,            line=dict(color=C["bg"], width=1)        ),        hovertemplate="<b>%{x}</b><br>%{y:,} transactions<extra></extra>",    ), secondary_y=False)    fig.add_trace(go.Scatter(        x=df["Ann\u00e9e"],        y=df["Note globale"],        name="Note globale",        mode="lines+markers+text",        line=dict(color=C["green"], width=3),        marker=dict(size=10, color=C["green"],                    line=dict(color=C["bg"], width=2)),        text=["{:.3f}".format(v) for v in df["Note globale"]],        textposition="top center",        textfont=dict(color=C["text"], size=10),        hovertemplate="<b>%{x}</b><br>Satisfaction : %{y:.3f}/5<extra></extra>",    ), secondary_y=True)    fig.add_trace(go.Scatter(        x=df["Ann\u00e9e"],        y=df["Score livraison"],        name="Score livraison",        mode="lines+markers",        line=dict(color=C["teal"], width=2, dash="dot"),        marker=dict(size=7, color=C["teal"]),        hovertemplate="<b>%{x}</b><br>Livraison : %{y:.3f}/5<extra></extra>",    ), secondary_y=True)    # apply_theme puis update separement pour eviter les doublons    apply_theme(fig, "Volume (barres) et satisfaction (courbes) - 2016-2020")    fig.update_layout(        height=380,        legend=dict(            orientation="h",            x=0.5, xanchor="center", y=1.08,            bgcolor=C["card2"],            bordercolor=C["border"]        )    )    fig.update_yaxes(title_text="Nb transactions", **AXIS_STYLE, secondary_y=False)    fig.update_yaxes(title_text="Note / 5", range=[4.80, 4.84],                     **AXIS_STYLE, secondary_y=True)    fig.update_xaxes(**AXIS_STYLE)    st.plotly_chart(fig, use_container_width=True)    # ── % International + Nb vendeurs ────────────────────────    col1, col2 = st.columns([3, 2])    with col1:        section_title("Taux d'internationalisation", "🌍")        fig2 = go.Figure(go.Scatter(            x=df["Ann\u00e9e"],            y=df["% International"],            mode="lines+markers+text",            fill="tozeroy",            fillcolor="rgba(26,115,232,0.13)",            line=dict(color=C["blue"], width=3),            marker=dict(size=9, color=C["blue"],                        line=dict(color=C["bg"], width=2)),            text=["{:.1f}%".format(v) for v in df["% International"]],            textposition="top center",            textfont=dict(color=C["text"], size=11),            hovertemplate="<b>%{x}</b><br>%{y:.1f}% international<extra></extra>",        ))        fig2.add_hrect(            y0=79, y1=79.5,            fillcolor=C["orange"], opacity=0.25,            annotation_text="Pic 2017 : 79.1%",            annotation_position="right",            annotation_font_color=C["orange"]        )        apply_theme(fig2, "")        fig2.update_layout(height=260, showlegend=False)        fig2.update_yaxes(range=[65, 85])        st.plotly_chart(fig2, use_container_width=True)    with col2:        section_title("Nb vendeurs actifs", "🏪")        fig3 = go.Figure(go.Bar(            x=df["Nb vendeurs"],            y=df["Ann\u00e9e"].astype(str),            orientation="h",            marker=dict(                color=df["Nb vendeurs"],                colorscale=[[0, C["card2"]], [1, C["purple"]]],                showscale=False,                line=dict(color=C["bg"], width=1)            ),            text=["{:,}".format(int(v)) for v in df["Nb vendeurs"]],            textposition="outside",            textfont=dict(color=C["text"]),            hovertemplate="<b>%{y}</b><br>%{x:,} vendeurs<extra></extra>",        ))        apply_theme(fig3, "")        fig3.update_layout(height=260, showlegend=False,                           margin=dict(l=10, r=60))        st.plotly_chart(fig3, use_container_width=True)    # ── Tableau recap ─────────────────────────────────────────    section_title("Recapitulatif annuel", "📋")    st.dataframe(        df.style        .background_gradient(subset=["Nb transactions"], cmap="Blues")        .background_gradient(subset=["Note globale"], cmap="RdYlGn",                             vmin=4.80, vmax=4.84)        .format({            "Nb transactions": "{:,}",            "Note globale": "{:.3f}",            "Score livraison": "{:.3f}",            "% International": "{:.1f}%",            "Nb vendeurs": "{:,}",        }),        use_container_width=True,        height=215    )